const email = $input.item.json;

// Extract key fields
const from = email.from?.value?.[0]?.address || email.from || 'Unknown';
const subject = email.subject || 'No Subject';
const body = (email.text || email.snippet || '').substring(0, 2000); // Limit body size
const date = email.date || new Date().toISOString();

// Detect Blackbaud / school portal emails
const fromLower = from.toLowerCase();
const subjectLower = subject.toLowerCase();
const isSchoolPortal = fromLower.includes('myschoolapp') || fromLower.includes('blackbaud') || fromLower.includes('stpcs') || subjectLower.includes('blackbaud') || subjectLower.includes('myschoolapp');

return [{
  json: {
    from,
    subject,
    body,
    date,
    emailId: email.id,
    isSchoolPortal,
    promptText: `From: ${from}\nSubject: ${subject}\nDate: ${date}\n\nBody:\n${body}`
  }
}];

const response = $input.item.json;
const emailData = $('Extract Email Fields').item.json;
let parsed;

try {
  parsed = JSON.parse(response.content[0].text);
} catch (e) {
  // Try to extract JSON from the response
  const match = response.content[0].text.match(/\{[\s\S]*\}/);
  if (match) {
    parsed = JSON.parse(match[0]);
  } else {
    parsed = {
      summary: 'Could not parse email',
      category: 'unknown',
      priority: 'low',
      has_event: false,
      has_action_item: false,
      notify_josh: false
    };
  }
}

// Blackbaud / school portal emails are always at least medium priority
if (emailData.isSchoolPortal && parsed.priority === 'low') {
  parsed.priority = 'medium';
}
if (emailData.isSchoolPortal) {
  parsed.category = 'school';
}

return [{
  json: {
    ...emailData,
    ...parsed,
    timestamp: new Date().toISOString(),
    source: emailData.isSchoolPortal ? 'blackbaud' : 'gmail'
  }
}];

const data = $input.item.json;
const priorityEmoji = { high: '\u2757', medium: '\u2755', low: '\u2139\uFE0F' };
const categoryEmoji = { school: '\uD83C\uDFEB', sports: '\u26BD', medical: '\uD83C\uDFE5', family: '\uD83D\uDC68\u200D\uD83D\uDC69\u200D\uD83D\uDC67', work: '\uD83D\uDCBC', social: '\uD83C\uDF89', bills: '\uD83D\uDCB0', spam: '\uD83D\uDEAB' };

let message = `${priorityEmoji[data.priority] || ''} ${data.category?.toUpperCase() || 'EMAIL'}\n\n`;
message += `From: ${data.from}\n`;
message += `Subject: ${data.subject}\n\n`;
message += `${data.summary}\n`;

if (data.has_event && data.event_details) {
  const e = data.event_details;
  message += `\nEvent Detected: ${e.title || 'TBD'}\n`;
  if (e.date) message += `Date: ${e.date}\n`;
  if (e.time) message += `Time: ${e.time}\n`;
  if (e.location) message += `Location: ${e.location}\n`;
}

if (data.has_action_item) {
  message += `\nAction needed: ${data.action_item}\n`;
}

message += `\nReply to this text to take action.`;

return [{ json: { message, to: 'YOUR_PHONE_NUMBER' } }];
